import json,os,re,sys
h=os.environ["SBX_HOME"]
root=os.path.join(h,"files")
def key(n):
    out=[]
    for p in re.split(r"(\d+)", n.lower()):
        if p=="": continue
        out.append((0,int(p)) if p.isdigit() else (1,p))
    return out
st=json.load(open(os.environ["STATE_FILE"]))
f=(st.get("views") or {}).get("files") or {}
rows=[r.get("name") for r in (f.get("rows") or [])]
names=[n for n in os.listdir(root) if not n.startswith(".")]
dirs=sorted([n for n in names if os.path.isdir(os.path.join(root,n))], key=key)
files=sorted([n for n in names if not os.path.isdir(os.path.join(root,n))], key=key)
want=[".."]+dirs+files
if rows!=want: sys.exit(1)
if "Item 2.txt" in rows and "Item 10.txt" in rows:
    if rows.index("Item 2.txt")+1!=rows.index("Item 10.txt"): sys.exit(1)
    if not rows.index("Item 10.txt")<rows.index("README.txt"): sys.exit(1)
else:
    sys.exit(1)
if f.get("selection")!=len(rows)-1: sys.exit(1)
if rows[-1]!="spaced name.txt": sys.exit(1)
sys.exit(0)
'

